<div class="tool-grid">
    <div class="tool-field"><label>Cable distance (metres)</label><input data-input="distance" type="number" min="0" value="100"></div>
    <div class="tool-field"><label>Route type</label><select data-input="route"><option value="indoor">Indoor trunking</option><option value="outdoor">Outdoor duct/aerial</option><option value="trenching">New trenching required</option></select></div>
    <div class="tool-field"><label>Termination points</label><input data-input="terminations" type="number" min="0" value="2"></div>
    <div class="tool-field"><label>Splice points</label><input data-input="splices" type="number" min="0" value="2"></div>
    <div class="tool-field"><label>Equipment allowance (KES)</label><input data-input="equipment" type="number" min="0" value="15000"></div>
    <div class="tool-field"><label>Labour level</label><select data-input="labour"><option value="standard">Standard</option><option value="complex">Complex route</option><option value="urgent">Urgent/after-hours</option></select></div>
</div>
<button class="tool-button mt-3" type="button" data-calculate>Calculate Cost</button>
